// @ts-check
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import rehypeBaseLinks from './plugins/rehype-base-links.mjs';

const REPO = 'https://github.com/kwangyoulsagong/aquila-agents';
const BASE = process.env.SITE_BASE ?? '/';

/** Sidebar group: label (en) + Korean label, pages autogenerated from docs/<dir> and ordered by `sidebar.order`. */
/** @param {string} label @param {string} ko @param {string} dir */
const group = (label, ko, dir) => ({
  label,
  translations: { ko },
  items: [{ autogenerate: { directory: `docs/${dir}` } }],
});

// Deploy target is set at build time: SITE_URL=https://example.com SITE_BASE=/aquila-agents npm run build
export default defineConfig({
  site: process.env.SITE_URL,
  base: BASE,
  markdown: { rehypePlugins: [rehypeBaseLinks({ base: BASE })] },
  trailingSlash: 'ignore',
  integrations: [
    starlight({
      title: 'Aquila Agents',
      description: 'Every Claude Code and Codex session, in one window.',
      logo: { src: '../build/icon.svg', alt: 'Aquila Agents' },
      favicon: '/icon.svg',
      defaultLocale: 'en',
      locales: {
        en: { label: 'English', lang: 'en' },
        ko: { label: '한국어', lang: 'ko' },
      },
      social: [{ icon: 'github', label: 'GitHub', href: REPO }],
      editLink: { baseUrl: `${REPO}/edit/main/site/` },
      lastUpdated: true,
      head: [{ tag: 'meta', attrs: { name: 'author', content: 'Kwangyoul Sagong' } }],
      customCss: ['./src/styles/docs.css'],
      components: {
        SiteTitle: './src/components/docs/SiteTitle.astro',
        Footer: './src/components/docs/Footer.astro',
      },
      sidebar: [
        { label: 'Overview', translations: { ko: '개요' }, slug: 'docs' },
        group('Get started', '시작하기', 'start'),
        group('Workspace', '작업 공간', 'workspace'),
        group('Working with agents', '에이전트와 일하기', 'agents'),
        group('Notes', '노트', 'notes'),
        group('Reference', '레퍼런스', 'reference'),
        group('Contributing', '기여하기', 'contributing'),
      ],
    }),
  ],
  vite: {
    // Guide media and the app icon are shared with the app, read from the repo root.
    server: { fs: { allow: ['..'] } },
  },
});
